function decompressRLElist(nums) {
  const result = [];
  for (let i = 0; i < nums.length; i += 2) {
    const freq = nums[i];
    const val = nums[i + 1];
    for (let k = 0; k < freq; k++) {
      result.push(val);
    }
  }
  return result;
}

