function decompressRLElist(nums) {
  let out = [];
  const pairs = [];
  for (let p = 0; p * 2 < nums.length; p++) pairs.push([nums[2 * p], nums[2 * p + 1]]);
  for (const [count, value] of pairs) out = out.concat(new Array(count).fill(value));
  return out;
}

